-- ============================================================================
-- seed_operacion_real.sql
-- ----------------------------------------------------------------------------
-- Configuración de la operación REAL (Lima <-> Surco) para reproducir el
-- sistema desde cero: paradas, vehículos/asientos, rutas, tramos, perfiles de
-- tiempo por franja, calendario y plantillas.
--
-- Pensado para una BD NUEVA, después de correr las migraciones (schema).
-- Idempotente con REPLACE; usa FOREIGN_KEY_CHECKS=0 por el orden de FKs.
--
-- NO incluye pasajeros ni la planilla: solo los 2 usuarios DRIVER con la
-- contraseña de desarrollo documentada ("12345678"). CAMBIARLA antes de prod.
--
-- Uso:  mariadb -u root transporte_corporativo_mvp < seed_operacion_real.sql
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- Conductores (placeholder de credenciales: 12345678)
ON DUPLICATE KEY UPDATE full_name = VALUES(full_name), employee_code = VALUES(employee_code);

/*M!999999\- enable the sandbox mode */ 
SET FOREIGN_KEY_CHECKS = 1;
